import ast, sys
for path in ("carbon_market/migration_batch.py", "carbon_market/migration_consumer.py"):
    tree = ast.parse(open(path).read())
    imported = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names: imported[(a.asname or a.name).split(".")[0]] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for a in node.names: imported[a.asname or a.name] = node.lineno
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name): used.add(node.id)
        elif isinstance(node, ast.Attribute):
            n = node
            while isinstance(n, ast.Attribute): n = n.value
            if isinstance(n, ast.Name): used.add(n.id)
    # names used inside strings (getattr) won't appear; check manually
    src = open(path).read()
    for name, line in imported.items():
        if name not in used and src.count(name) < 2:
            print(f"{path}:{line}: possibly unused import {name}")
print("done")
